// ── Google, Amazon Inspector and Microsoft ─────────────────────────────────────────────────────────────────────────

// Equivalence classes of the packages of the SBOMs Trivy, Google Artifact Analysis (artifactanalysis-0.1), Amazon
// Inspector and Microsoft's SBOM tool (2.2.9) made of 40 images, in the SBOMVert dataset
// (https://box.roc.cnam.fr/index.php/s/XQRa9dXz7bpWGRf, SPDX only), made on 2026-11-14. Classes are cut from Trivy's
// view of a package (its type, epoch, source, architecture, a version without a Debian revision, a binNMU; for Go the
// module's kind, for npm a scope, for Composer the version's `v`), and each has one package found by Trivy and the
// others, as each wrote it: its purl (none for Microsoft's Alpine packages: their name instead), its version, Trivy's
// `sourceInfo`, and the source package Inspector lists apart (`source`). Microsoft lists only OS packages.

export type CloudTool = 'trivy' | 'google' | 'amazon' | 'microsoft';

export type CloudRepresentation = {
  purl?: string;
  name?: string; // a package without a purl (Microsoft's Alpine packages)
  version?: string;
  sourceInfo?: string; // Trivy
  source?: CloudRepresentation; // Inspector: the source package, listed as a package of its own
};

export type CloudClass = { label: string; image: string } & Partial<
  Record<CloudTool, CloudRepresentation>
>;

